import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
  requireTestDatabaseUrl,
} from "./helpers/foundation-db";

describe("usage database isolation guard", () => {
  it("rejects remote, non-test and query-overridden destinations", () => {
    for (const target of [
      "postgresql://example.com/app_test",
      "postgresql://localhost/app",
      "postgresql://127.0.0.1/app_test_backup",
      "https://localhost/app_test",
      "postgresql://localhost/app_test?host=example.com",
      "postgresql://localhost/app_test?hostaddr=10.0.0.1",
      "postgresql://localhost/app_test?port=5432",
      "postgresql://localhost/app_test?dbname=mailloop",
    ])
      expect(() => requireTestDatabaseUrl(target)).toThrow("local _test");
    expect(
      requireTestDatabaseUrl("postgresql://127.0.0.1:5434/app_test").pathname,
    ).toBe("/app_test");
  });
});

const migrationName = "20261016020000_usage_ledger";
describe.runIf(databaseTestsEnabled)("usage ledger additive migration", () => {
  let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
  const query = (sql: string, args?: unknown[]) =>
    fixture.client.query(sql, args);
  let legacy: Record<string, Record<string, unknown>[]>;
  beforeAll(async () => {
    fixture = await createIsolatedDatabase();
    try {
      for (const name of fixture.migrations.filter(
        (name) => name < migrationName,
      ))
        await fixture.apply(name);
      await query(`
        INSERT INTO "User" (id,email) VALUES ('owner','[REDACTED_EMAIL]'),('other','[REDACTED_EMAIL]');
        INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ('template','owner','Legacy','Subject','Body');
        INSERT INTO "Contact" (id,"userId",name,email) VALUES ('contact','owner','Ada','[REDACTED_EMAIL]');
        INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ('campaign','owner','template','COMPLETED');
        INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","sentAt") VALUES ('sent','campaign','contact','SENT','DONE',now()),('queued','campaign','contact','QUEUED','READY',NULL);
        INSERT INTO "DeliveryReceipt" (id,"userId","recipientEmail","createdAt","sentAt") VALUES ('receipt','owner','[REDACTED_EMAIL]',now(),now());
      `);
      legacy = {};
      for (const table of [
        "User",
        "Send",
        "DeliveryReceipt",
        "Campaign",
        "Contact",
        "Template",
      ])
        legacy[table] = (
          await query(`SELECT * FROM "${table}" ORDER BY id`)
        ).rows;
      await fixture.apply(migrationName);
    } catch (error) {
      await fixture.cleanup();
      throw error;
    }
  });
  afterAll(async () => {
    if (fixture) await fixture.cleanup();
  });

  it("preserves every legacy value and leaves old queues unmodified", async () => {
    for (const [table, rows] of Object.entries(legacy)) {
      const actual = (await query(`SELECT * FROM "${table}" ORDER BY id`)).rows;
      rows.forEach((row, index) => expect(actual[index]).toMatchObject(row));
    }
    expect(
      (await query(`SELECT * FROM "Send" WHERE id='queued'`)).rows[0],
    ).toMatchObject({
      availableAt: null,
      queueExpiresAt: null,
      claimToken: null,
      leaseExpiresAt: null,
      dispatchGeneration: 0,
      dispatchAttempts: 0,
      dispatchAttemptedAt: null,
    });
    expect(
      (await query(`SELECT * FROM "User" WHERE id='owner'`)).rows[0],
    ).toMatchObject({ usageBackfillVersion: 0, usageCutoverAt: null });
    expect((await query('SELECT * FROM "UsagePeriod"')).rows).toEqual([]);
    expect((await query('SELECT * FROM "UsageReservation"')).rows).toEqual([]);
    expect((await query('SELECT * FROM "UsageImportEvidence"')).rows).toEqual(
      [],
    );
  });

  it("enforces counter, period, claim and timestamp-provenance constraints", async () => {
    await query(`INSERT INTO "UsagePeriod" (id,"userId",key,kind,"startsAt","endsAt","operationalEndsAt") VALUES
      ('day','owner','day','DAILY','2026-10-16','2026-10-17','2026-10-17'),
      ('month','owner','month','MONTHLY','2026-10-01','2026-11-01','2026-11-01'),
      ('other-day','other','day','DAILY','2026-10-16','2026-10-17','2026-10-17');`);
    for (const patch of [
      "sent=-1",
      "reserved=-1",
      '"importedSent"=1',
      '"importedReserved"=1',
      '"startsAt"="endsAt"',
      '"operationalEndsAt"="startsAt"',
      "key=' '",
    ])
      await expect(
        query(`UPDATE "UsagePeriod" SET ${patch} WHERE id='day'`),
      ).rejects.toMatchObject({ code: "23514" });
    await expect(
      query(`UPDATE "Send" SET "dispatchAttempts"=-1 WHERE id='queued'`),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      query(`UPDATE "Send" SET "claimToken"='token' WHERE id='queued'`),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      query(`UPDATE "User" SET "usageBackfillVersion"=-1 WHERE id='owner'`),
    ).rejects.toMatchObject({ code: "23514" });
    await query(
      `INSERT INTO "UsageReservation" (id,"userId","deliveryKey","sendId","dailyPeriodId","monthlyPeriodId") VALUES ('reservation','owner','delivery','sent','day','month')`,
    );
    await expect(
      query(
        `UPDATE "UsageReservation" SET status='ATTEMPTING' WHERE id='reservation'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      query(
        `UPDATE "UsageReservation" SET "dailyPeriodId"='other-day' WHERE id='reservation'`,
      ),
    ).rejects.toMatchObject({ code: "23503" });
    await query(
      `INSERT INTO "UsageImportEvidence" (id,"userId","sourceKey","chargedAt","timestampSource") VALUES ('evidence','owner','send:historical','2026-10-16','sentAt')`,
    );
    await expect(
      query(
        `UPDATE "UsageImportEvidence" SET "timestampSource"='createdAt' WHERE id='evidence'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      query(
        `INSERT INTO "UsageImportEvidence" SELECT 'duplicate',"userId","sourceKey","deliveryKey","chargedAt","timestampSource","createdAt" FROM "UsageImportEvidence" WHERE id='evidence'`,
      ),
    ).rejects.toMatchObject({ code: "23505" });
    await query(
      `UPDATE "DeliveryReceipt" SET "deliveryKey"='delivered' WHERE id='receipt'`,
    );
    await expect(
      query(
        `INSERT INTO "DeliveryReceipt" (id,"userId","recipientEmail","createdAt","sentAt","deliveryKey") VALUES ('duplicate','owner','[REDACTED_EMAIL]',now(),now(),'delivered')`,
      ),
    ).rejects.toMatchObject({ code: "23505" });
  });

  it("retains reservations and evidence through send/history deletion", async () => {
    await query(
      `DELETE FROM "Send" WHERE id='sent'; DELETE FROM "DeliveryReceipt" WHERE id='receipt'`,
    );
    expect(
      (
        await query(
          `SELECT "sendId","deliveryKey" FROM "UsageReservation" WHERE id='reservation'`,
        )
      ).rows,
    ).toEqual([{ sendId: null, deliveryKey: "delivery" }]);
    expect(
      (
        await query(
          `SELECT count(*)::int AS n FROM "UsageImportEvidence" WHERE "userId"='owner'`,
        )
      ).rows[0].n,
    ).toBe(1);
  });

  it("creates all indexes and retains TEXT IDs and millisecond timestamps", async () => {
    const sql = await readFile(
      `prisma/migrations/${migrationName}/migration.sql`,
      "utf8",
    );
    const indexes = (
      await query("SELECT indexname FROM pg_indexes WHERE schemaname=$1", [
        fixture.schema,
      ])
    ).rows.map((r) => r.indexname);
    for (const match of sql.matchAll(/CREATE (?:UNIQUE )?INDEX "([^"]+)"/g))
      expect(indexes).toContain(match[1]);
    const columns = (
      await query(
        `SELECT column_name,data_type,datetime_precision FROM information_schema.columns WHERE table_schema=$1 AND table_name IN ('UsagePeriod','UsageReservation','UsageImportEvidence')`,
        [fixture.schema],
      )
    ).rows;
    for (const column of columns) {
      if (column.column_name === "id") expect(column.data_type).toBe("text");
      if (column.data_type === "timestamp without time zone")
        expect(column.datetime_precision).toBe(3);
    }
    // Existing UUID generation remains in the client, not a new SQL extension.
    const id = randomUUID();
    await query(
      `INSERT INTO "UsageImportEvidence" (id,"userId","sourceKey","chargedAt","timestampSource") VALUES ($1,'owner',$1,now(),'attemptedAt')`,
      [id],
    );
    expect(
      (await query('SELECT id FROM "UsageImportEvidence" WHERE id=$1', [id]))
        .rows[0].id,
    ).toBe(id);
  });
});
